def contains_year(text, year_text):
    start = 0
    while True:
        position = text.find(year_text, start)
        if position < 0:
            return False
        before_ok = position == 0 or not text[position - 1].isdigit()
        end = position + len(year_text)
        after_ok = end == len(text) or not text[end].isdigit()
        if before_ok and after_ok:
            return True
        start = position + 1

def money_text_to_cents(text):
    negative = False
    started = False
    numeric_chars = []
    for ch in text:
        if not started:
            if ch == '-':
                negative = True
            elif ch.isdigit():
                numeric_chars.append(ch)
                started = True
        elif ch.isdigit() or ch in '.,':
            numeric_chars.append(ch)
        else:
            break
    raw_number = ''.join(numeric_chars).replace(',', '').rstrip('.')
    if not raw_number or raw_number.count('.') > 1:
        return None
    parts = raw_number.split('.')
    whole = parts[0] or '0'
    fraction = parts[1] if len(parts) == 2 else ''
    if not whole.isdigit() or (fraction and not fraction.isdigit()) or len(fraction) > 2:
        return None
    cents = int(whole) * 100 + int((fraction + '00')[:2])
    return -cents if negative else cents

def extract_labeled_amount_options(content):
    lowered = content.lower()
    label_groups = [('total amount due', 'total_amount_due'), ('amount due', 'amount_due'), ('balance due', 'balance_due'), ('grand total', 'grand_total'), ('total amount', 'total_amount'), ('total cost', 'total_cost'), ('bill total', 'bill_total'), ('total',), ('amount',), ('cost',), ('price',)]
    for labels in label_groups:
        values = []
        for label in labels:
            start = 0
            while True:
                position = lowered.find(label, start)
                if position < 0:
                    break
                end = position + len(label)
                before_ok = position == 0 or not (lowered[position - 1].isalnum() or lowered[position - 1] == '_')
                after_ok = end == len(lowered) or not (lowered[end].isalnum() or lowered[end] == '_')
                if before_ok and after_ok:
                    cents = money_text_to_cents(content[end:])
                    if cents is not None:
                        values.append(cents)
                start = position + len(label)
        unique_values = sorted(set(values))
        if unique_values:
            return unique_values
    return []

